-- Insert Lessons (5 Chapters)
INSERT INTO public.lessons (chapter_number, title, description, order_index, duration_mins, objectives, content_blocks, reflection_question) VALUES
(1, 'ประพจน์ (Propositions)', 'เรียนรู้ความหมายของประพจน์ การแยกแยะประโยคที่เป็นประพจน์และไม่เป็นประพจน์ ในโลกตรรกศาสตร์คอมพิวเตอร์', 1, 15, 
'["บอกความหมายของประพจน์ได้ถูกต้อง", "จำแนกประโยคบอกเล่า/ปฏิเสธที่เป็นประพจน์ได้", "ระบุประโยคที่ไม่เป็นประพจน์ (คำสั่ง, คำถาม, ขอร้อง) ได้"]'::jsonb,
'[
  {"type": "card", "title": "ประพจน์คืออะไร?", "body": "ประพจน์ (Proposition) คือ ประโยคบอกเล่าหรือประโยคปฏิเสธที่มีค่าความจริงเป็น **จริง (True)** หรือ **เท็จ (False)** อย่างใดอย่างหนึ่งเท่านั้น!"},
  {"type": "interactive", "title": "ทดลองแยกแยะประพจน์", "body": "ลองพิจารณาประโยคต่อไปนี้: \'กรุงเทพฯ เป็นเมืองหลวงของไทย\' ➔ เป็นประพจน์ (จริง)"},
  {"type": "knowledge_check", "title": "ประโยคใดต่อไปนี้ **ไม่เป็น** ประพจน์?", "options": ["2 + 3 = 5", "โปรดเอื้อเฟื้อแก่เด็กและสตรีมีครรภ์", "เชียงใหม่ยินดีต้อนรับ", "ดวงอาทิตย์ขึ้นทางทิศตะวันออก"], "correct": 1, "explanation": "ประโยคขอร้อง คำสั่ง คำถาม และคำอวยพร ไม่สามารถบอกได้ว่าเป็นจริงหรือเท็จ จึงไม่เป็นประพจน์"}
]'::jsonb,
'นักเรียนคิดว่าประโยคในชีวิตประจำวัน เช่น "โปรแกรมนี้ทำงานเร็วมาก" เป็นประพจน์หรือไม่? เพราะเหตุใด?'),

(2, 'ค่าความจริง (Truth Values)', 'การกำหนดค่าความจริง True (T / 1) และ False (F / 0) ในระบบดิจิทัลและตรรกศาสตร์', 2, 15, 
'["เข้าใจค่าความจริง T (จริง) และ F (เท็จ)", "เชื่อมโยงค่าความจริงกับสัญญาณดิจิทัล 1 และ 0 ในคอมพิวเตอร์ได้"]'::jsonb,
'[
  {"type": "card", "title": "จริง (T) vs เท็จ (F)", "body": "ในทางคอมพิวเตอร์ ค่าความจริงถูกแทนด้วย **1 (True / High Voltage)** และ **0 (False / Low Voltage)**"},
  {"type": "flip_card", "title": "คลิกเพื่อดูสัญลักษณ์", "front": "True (จริง)", "back": "สัญลักษณ์: T หรือ 1"},
  {"type": "flip_card", "title": "คลิกเพื่อดูสัญลักษณ์", "front": "False (เท็จ)", "back": "สัญลักษณ์: F หรือ 0"}
]'::jsonb,
'ทำไมคอมพิวเตอร์ถึงใช้ค่าความจริง 1 และ 0 ในการประมวลผลคำสั่งเชิงตรรกะ?'),

(3, 'ตัวเชื่อมตรรกศาสตร์ (Logical Connectives)', 'เจาะลึกตัวเชื่อมทั้ง 6 แบบ: NOT (~), AND (∧), OR (∨), XOR (⊕), IF-THEN (→), IFF (↔)', 3, 25, 
'["เข้าใจการทำงานของ NOT, AND, OR, XOR, IF-THEN, IFF", "คำนวณค่าความจริงของประพจน์เชิงซ้อนได้"]'::jsonb,
'[
  {"type": "diagram", "title": "แผนภาพตัวเชื่อมตรรกศาสตร์", "connectives": ["NOT (~)", "AND (∧)", "OR (∨)", "XOR (⊕)", "IF-THEN (→)", "IFF (↔)"]},
  {"type": "rule", "title": "กฎความจำฉบับนักสืบ", "rules": ["AND: จริงเมื่อ \'จริงทั้งคู่\'", "OR: เท็จเมื่อ \'เท็จทั้งคู่\'", "IF-THEN: เท็จกรณีเดียวคือ \'หน้าจริง หลังเท็จ\'", "IFF: จริงเมื่อ \'เหมือนกัน\'"]}
]'::jsonb,
'หากเงื่อนไขในการเข้าประตูห้องความลับคือ "ต้องมีคีย์การ์ด OR ต้องรู้รหัสผ่าน" หากเรามีคีย์การ์ดแต่ไม่รู้รหัสผ่าน ประตูจะเปิดหรือไม่?'),

(4, 'ตารางค่าความจริง (Truth Table)', 'การสร้างและวิเคราะห์ตารางค่าความจริงเพื่อหาผลลัพธ์ของประพจน์ในทุกกรณี', 4, 30, 
'["คำนวณจำนวนกรณี 2^n ในตารางค่าความจริงได้", "เติมค่าความจริงในตารางค่าความจริงได้อย่างแม่นยำ"]'::jsonb,
'[
  {"type": "card", "title": "สูตรจำนวนกรณี 2^n", "body": "หากมี 2 ประพจน์ (p, q) จะมี 2^2 = 4 กรณี หากมี 3 ประพจน์ (p, q, r) จะมี 2^3 = 8 กรณี"},
  {"type": "interactive_truth_table", "title": "ฝึกเติมตารางค่าความจริง p ∧ q", "p": [true, true, false, false], "q": [true, false, true, false]}
]'::jsonb,
'การเขียนตารางค่าความจริงมีประโยชน์อย่างไรในการออกแบบวงจรตรรกะ (Logic Gate) ของคอมพิวเตอร์?'),

(5, 'การให้เหตุผลเชิงตรรกะ (Logical Reasoning)', 'การตรวจสอบความสมเหตุสมผลของข้อสรุปจากเหตุที่กำหนด (Syllogism & Deduction)', 5, 25, 
'["อธิบายการให้เหตุผลแบบนิรนัย (Deductive) ได้", "ตรวจสอบความสมเหตุสมผล (Validity) ของการอ้างเหตุผลได้"]'::jsonb,
'[
  {"type": "card", "title": "การอ้างเหตุผลสมเหตุสมผล", "body": "การอ้างเหตุผลจะสมเหตุสมผลเมื่อ เหตุทุกข้อเป็นจริง แล้วข้อสรุป **ต้องเป็นจริง** เสมอ!"},
  {"type": "case_study", "title": "คดีปริศนานักสืบ", "scenario": "เหตุ 1: ถ้าฝนตก แล้วถนนจะเปียก | เหตุ 2: วันนี้ฝนตก | สรุป: ถนนเปียก", "is_valid": true}
]'::jsonb,
'การคิดเชิงตรรกะและเหตุผลช่วยให้นักเรียนแก้ปัญหาในการเขียนโปรแกรมได้อย่างไร?')
ON CONFLICT (chapter_number) DO NOTHING;

-- Insert Seed Question Bank (20 Questions for Pre/Post Tests)
INSERT INTO public.question_bank (chapter_number, question_text, options, correct_option_index, explanation, difficulty) VALUES
(1, 'ข้อใดต่อไปนี้เป็น "ประพจน์"?', '["อย่าเดินลัดสนาม", "กรุงเทพมหานครเป็นเมืองหลวงของไทย", "เธอชอบเรียนตรรกศาสตร์ไหม", "ว้าว! สวยจังเลย"]'::jsonb, 1, 'กรุงเทพฯ เป็นเมืองหลวงของไทย เป็นประโยคบอกเล่าที่มีค่าความจริงเป็นจริง จึงเป็นประพจน์', 'easy'),
(1, 'ข้อใดต่อไปนี้ **ไม่เป็น** ประพจน์?', '["5 มากกว่า 3", "2 เป็นจำนวนคู่", "กรุณาปิดไฟก่อนออกจากห้อง", "เดือนมกราคมมี 31 วัน"]'::jsonb, 2, 'กรุณาปิดไฟก่อนออกจากห้อง เป็นประโยคขอร้อง จึงไม่เป็นประพจน์', 'easy'),
(2, 'ประพจน์ "3 + 4 = 8" มีค่าความจริงตรงกับข้อใด?', '["จริง (T)", "เท็จ (F)", "ไม่สามารถระบุได้", "เป็นจริงและเท็จพร้อมกัน"]'::jsonb, 1, 'เพราะ 3 + 4 = 7 ไม่เท่ากับ 8 ประพจน์นี้จึงมีค่าความจริงเป็น เท็จ (F)', 'easy'),
(2, 'สัญลักษณ์ใดยอดนิยมที่ใช้แทนค่าความจริง "จริง" ในระบบคอมพิวเตอร์ดิจิทัล?', '["0", "1", "-1", "NULL"]'::jsonb, 1, 'ในระบบดิจิทัล 1 แทน True (จริง) และ 0 แทน False (เท็จ)', 'easy'),
(3, 'กำหนดให้ p เป็นจริง, q เป็นเท็จ ข้อใดมีค่าความจริงเป็น **จริง**?', '["p ∧ q", "p → q", "p ∨ q", "~p"]'::jsonb, 2, 'p ∨ q (จริง หรือ เท็จ) ได้ค่าความจริงเป็น จริง (T)', 'medium'),
(3, 'ตัวเชื่อมประเภทใดที่จะให้ค่าความจริงเป็น "เท็จ" เมื่อประพจน์หน้าเป็นจริง และประพจน์หลังเป็นเท็จเท่านั้น?', '["AND (และ)", "OR (หรือ)", "IF-THEN (ถ้า...แล้ว...)", "IFF (ก็ต่อเมื่อ)"]'::jsonb, 2, 'เงื่อนไข p → q จะเป็นเท็จกรณีเดียวคือ p เป็นจริง และ q เป็นเท็จ (T → F ≡ F)', 'medium'),
(3, 'ประพจน์ ~p ∧ p มีค่าความจริงเป็นอย่างไรเสมอ?', '["เป็นจริงเสมอ", "เป็นเท็จเสมอ", "ขึ้นอยู่กับค่าของ p", "เป็นจริงเมื่อ p เป็นเท็จ"]'::jsonb, 1, 'เนื่องจาก ~p และ p มีค่าความจริงตรงข้ามกันเสมอ เมื่อนำมาเชื่อมด้วย AND ผลลัพธ์จึงเป็นเท็จ (F) เสมอ', 'medium'),
(4, 'ถ้าประพจน์มี 3 ตัวแปร (p, q, r) ตารางค่าความจริงจะมีจำนวนกรณีทั้งหมดกี่กรณี?', '["4 กรณี", "6 กรณี", "8 กรณี", "16 กรณี"]'::jsonb, 2, 'ใช้สูตร 2^n ➔ 2^3 = 8 กรณี', 'medium'),
(4, 'ประพจน์ p ↔ q จะมีค่าความจริงเป็น "จริง" ในกรณีใด?', '["เมื่อ p และ q มีค่าความจริงเหมือนกัน", "เมื่อ p เป็นจริงเท่านั้น", "เมื่อ q เป็นเท็จเท่านั้น", "เมื่อ p และ q มีค่าความจริงต่างกัน"]'::jsonb, 0, 'ตัวเชื่อม "ก็ต่อเมื่อ" (IFF) จะเป็นจริงเมื่อประพจน์ทั้งสองมีค่าความจริงเหมือนกัน (T↔T=T, F↔F=T)', 'medium'),
(5, 'การอ้างเหตุผลต่อไปนี้: "เหตุ 1: ถ้าเป็นนักเรียน ปวช. แล้วต้องแต่งตัวเรียบร้อย | เหตุ 2: สมชายเป็นนักเรียน ปวช. | สรุป: สมชายแต่งตัวเรียบร้อย" สมเหตุสมผลหรือไม่?', '["สมเหตุสมผล (Valid)", "ไม่สมเหตุสมผล (Invalid)", "ข้อมูลไม่เพียงพอ", "สรุปเป็นเท็จ"]'::jsonb, 0, 'เป็นการอ้างเหตุผลตามรูปแบบ Modus Ponens (ถ้า p แล้ว q, เกิด p ➔ ดังนั้นเกิด q) ซึ่งสมเหตุสมผล', 'hard');
